#!/usr/bin/env python3
"""Reproduce this planning audit. No model calls, source acquisition or runtime edits.
Usage: python3 recalculate.py --tool-root /path/to/persona-distiller
"""
import argparse,hashlib,importlib.util,json,subprocess,sys
from pathlib import Path
ap=argparse.ArgumentParser();ap.add_argument('--tool-root',type=Path,required=True);a=ap.parse_args()
B=Path(__file__).resolve().parent;P=B.parents[2];tool=a.tool_root.resolve()
def read(p):return json.loads(p.read_text())
def put(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def load(name):
 s=importlib.util.spec_from_file_location(name,tool/'scripts'/(name+'.py'));m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
I=read(B/'inventory.json');M=read(B/'source-mass.json');tc=load('token_count');cb=load('cluster_budget')
spec={'words_firsthand':M['denominator_words'],'clusters':[{'cluster_id':n,'words':M['modules'][n]['words'],**c['counts']} for n,c in I['clusters'].items()]}
put(B/'cluster-inputs.json',spec)
subprocess.run([sys.executable,str(tool/'scripts/cluster_budget.py'),str(B/'cluster-inputs.json'),'--json',str(B/'cluster-calculation.json')],check=True,stdout=subprocess.DEVNULL)
rows=[]
def add(path,target,counts,breakdown,decision,sensitivity=None):
 actual=tc.count(str(P/path),1/.6,1.3);actual['file']=path;delta=round(actual['tokens_est']-target,2)
 row={'path':path,'target_tokens':target,'actual_tokens':actual['tokens_est'],'delta_tokens':delta,'delta_percent':round(100*delta/target,2),'within_ten_percent':abs(delta)<=.1*target,'target_kind':'source-grounded editorial planning target, not research-certified budget','counts':counts,'formula_terms':breakdown,'measurement':actual,'sha256':sha(P/path),'decision':decision}
 if sensitivity:row['sensitivity']=sensitivity
 rows.append(row)
C=I['core'];counts={k:len(C[k]) for k in ['cost_refusal','projectible','procedure','verdict','interactional','variation']};terms={'frame':2200}
for key,price,cap in [('cost_refusal',250,6),('projectible',180,7),('procedure',200,5),('verdict',150,8),('interactional',140,5),('variation',120,4)]:terms[key]=price*min(counts[key],cap)
core_supply=sum(terms.values());core_target=max(3000,min(core_supply,M['core_ceiling_inputs']['ceiling']))
add('SKILL.md',core_target,counts,terms,'KEEP COMPACT by explicit user instruction. Detailed argument chains live in mandatory standing modules and topic references; the numerical shortfall is not filled. Implementation safeguards are excluded from persona-supply counts.',{'corpus_ceiling':M['core_ceiling_inputs']['ceiling'],'target_with_conservative_4000_ceiling':max(3000,min(core_supply,4000))})
F=I['frameworks'];counts={k:len(v) for k,v in F.items()};terms={'frame':700}
for key,price,cap in [('constructs',120,20),('procedure',200,6),('epistemic',130,6),('verdict',90,24),('moves',110,10),('personal',70,6)]:terms[key]=price*min(counts[key],cap)
terms['construct_index_allowance']=25*min(counts['constructs'],40)
add('references/frameworks.md',max(2000,min(sum(terms.values()),7000)),counts,terms,'KEEP. The legacy formula budgets separate entries and an index; current prose combines them and routes concrete cases to topic modules. Do not duplicate those cases or add an index solely to consume the allowance.')
V=I['voice'];counts={k:len(V[k]) for k in ['registers','rules','avoid','pairs','nopool_pairs']};counts['within_family_gradient']=V['within_family_gradient'];terms={'frame':600,'registers':550*min(counts['registers'],4),'gradient':250*bool(counts['within_family_gradient']),'rules':90*min(counts['rules'],18),'avoid':40*min(counts['avoid'],25),'pairs':120*min(counts['pairs'],8),'nopool_pairs':60*min(counts['nopool_pairs'],6)}
add('references/voice.md',max(2000,min(sum(terms.values()),7000)),counts,terms,'KEEP. Five evidenced expressive occasions are represented concisely; they are not five statistically certified families. No quantified avoidance table or artificial contrast pairs are added to satisfy a legacy layout.',{'single_family_target':max(2000,min(sum(terms.values())-terms['registers']+550,7000))})
for name,c in I['clusters'].items():
 counts=c['counts'];words=M['modules'][name]['words'];supply,target,terms,floor,recut,regs=cb.compute(counts,words,M['denominator_words'],9,counts['registers'])
 assert not floor and not recut
 no_mass=sum(terms.values())-terms['mass'];one_reg=no_mass-terms['registers']
 add(c['path'],target,counts,terms,'KEEP. '+c['retention_decision'],{'source_mass_term_range':[0,400],'target_range_for_unknown_full_mass':[max(1800,min(no_mass,6000)),max(1800,min(no_mass+400,6000))],'single_register_target_same_mass':max(1800,min(one_reg+terms['mass'],6000))})
actual={r['path']:r['actual_tokens'] for r in rows};baseline=sum(actual[k] for k in ['SKILL.md','references/frameworks.md','references/voice.md']);topics=[r for r in rows if '/clusters/' in r['path']]
result={'schema_version':1,'basis_commit':I['basis_commit'],'method':'Default scoring.md size formulas with documented editorial counts and source-mass mapping; no empirical admission scores or certified register measurements are fabricated.','coefficients_changed':False,'module_coefficients':cb.coefficient_set(),'tokenizer':{'kind':'heuristic, not a model-specific BPE count','tokens_per_han_char':1/.6,'tokens_per_latin_word':1.3,'digit_run_base':1.2,'digit_length_divisor':3,'punctuation_run':1,'whitespace_run':1},'formula_source_hashes':{n:sha(tool/n) for n in ['references/scoring.md','scripts/token_count.py','scripts/cluster_budget.py']},'inventory_sha256':sha(B/'inventory.json'),'source_mass_sha256':sha(B/'source-mass.json'),'modules':rows,'runtime_load':{'actual_default':round(baseline,2),'actual_plus_two_largest_distinct_topics':round(baseline+sum(sorted(r['actual_tokens'] for r in topics)[-2:]),2),'actual_all_runtime':round(sum(actual.values()),2),'actual_refs_total':round(sum(v for k,v in actual.items() if k!='SKILL.md'),2),'legacy_two_module_formula':core_target+2*max(r['target_tokens'] for r in topics)+rows[1]['actual_tokens']+rows[2]['actual_tokens'],'loading_limit':'Current routing permits more than two topic modules. The legacy two-module formula is a comparison scenario, not an enforced worst-case ceiling. User input, history, tool output and response allowance are additional.'},'runtime_modified':False,'new_evaluation_calls':0,'strict_research_budget_compliance':'not_established; this is a retrospective planning audit under the explicit no-new-tests instruction'}
put(B/'results.json',result)
lines=['# Runtime budget audit — 2026-10-31','The user requested budgets for the compact core and every runtime reference, with no padding and no new tests. This audit lists a reproducible planning target, actual size and residual for all 13 files. It preserves the runtime at commit `'+I['basis_commit']+'`.',
'**These are editorial planning targets, not a completed research-admission calculation.** The original size coefficients are unchanged. Missing transfer, pressure and register-discrimination measurements remain unknown. The source-supported census replaces the legacy scored-survivor input only for this explicitly scoped planning use; it does not certify those survivors. The user’s compact-entry instruction takes precedence over filling a numerical target.',
'## Target and actual size','Counts use Persona-Distiller’s heuristic tokenizer, including frontmatter. They are not actual model token bills. Delta = actual − target; percentage = delta / target. ±10% is a comparison signal, not a command to pad or cut.',
'| Runtime file | Planning target | Actual | Delta | Delta % | Disposition |','|---|---:|---:|---:|---:|---|']
for r in rows:lines.append(f'| `{r["path"]}` | {r["target_tokens"]:,.0f} | {r["actual_tokens"]:,.2f} | {r["delta_tokens"]:+,.2f} | {r["delta_percent"]:+.2f}% | '+('Within ±10%; retain' if r['within_ten_percent'] else 'Documented exception; retain')+' |')
lines+=['','## What was counted','[Inventory](inventory.json) enumerates every counted concept, move, application and evidence passage with F-record source locators. These are already retained material, not new personality claims. A repeated episode is not independent corroboration. Cross-module conceptual homes are editorial assignments for accounting, not fixed roles assigned to books.','The voice already distinguishes scholarly exposition, public explanation, friendly dialogue, polemic and personal vulnerability. They supply provisional register-cost inputs; they are not empirical register families. Absent measured gradients, quantified avoidance entries, paired anti-drift demonstrations and no-pooling comparisons are not fabricated. Results include sensitivity to one register.','[Source mass](source-mass.json) records supplied-text hashes, eligible line ranges and exact counts. The pool keeps source-authored context and joint work with attribution, removes editorial opening material, keeps DG turns in dialogues, and removes the identified UT reprints of UR/BJ passages. It is not a count of exclusively Graeber-spoken words: embedded attributed quotations remain primary-source context. Only explicit located spans contribute module mass; chapter-only pointers are conservatively omitted. Module overlaps do not make sources independent. This documented mapping adapts the old `words_firsthand` parameter to a cross-book package; results expose the 0–400-token sensitivity rather than pretending the mass estimate is exact completeness.','The core ceiling uses the documented primary-context pool, ten current thematic groups and represented periods. These are editorial source groups, not ten independent books or certified statistical clusters. The lower-ceiling sensitivity is also recorded.','The inventory was made after the existing prose, so it is a retrospective audit, not evidence of prospective sizing or independent calibration. Default coefficients were not tuned to the observed lengths.',
'## Decisions by module']
for r in rows:lines+=['### '+r['path'],r['decision'],'Counts: `'+json.dumps(r['counts'],sort_keys=True)+'`. Formula contributions: `'+json.dumps(r['formula_terms'],sort_keys=True)+'`.']
lines+=['## Loading cost',f'Default core + voice + frameworks: **{baseline:,.2f}** estimated tokens. With the two largest distinct topic files: **{result["runtime_load"]["actual_plus_two_largest_distinct_topics"]:,.2f}**. All runtime files together: **{result["runtime_load"]["actual_all_runtime"]:,.2f}**.',result['runtime_load']['loading_limit'],
'## Reproduction and validation','Run `python3 transworld-identity/budgets/2026-10-31/recalculate.py --tool-root /path/to/persona-distiller` from the checkout. It calls the metatool cluster calculator and tokenizer, and reproduces the saved targets and residuals from the inspectable census. [Cluster inputs](cluster-inputs.json), [raw cluster calculation](cluster-calculation.json) and [full results](results.json) retain parameters and formula hashes. To reproduce source-mass counts first, run `python3 transworld-identity/budgets/2026-10-31/source_mass.py --sources /path/to/supplied/transcriptions`; it requires the matching supplied files. Their raw text is not distributed.','No runtime passage was added, removed or rewritten to change a residual. The module review found no source defect requiring a content correction in this budget-only pass. No new test case, generated answer, judge call or retry was added. Existing diagnostic applicability and Candidate status remain unchanged; budget arithmetic supplies no new recognition evidence.']
table_start = next(i for i, line in enumerate(lines) if line.startswith('| Runtime file'))
table_end = table_start + 2 + len(rows)
(B/'report.md').write_text('\n\n'.join(lines[:table_start])+'\n\n'+'\n'.join(lines[table_start:table_end])+'\n\n'+'\n\n'.join(line for line in lines[table_end:] if line)+'\n')
print('\n'.join(f'{r["path"]:48} target={r["target_tokens"]:5} actual={r["actual_tokens"]:8.2f} delta={r["delta_percent"]:+7.2f}%' for r in rows))
